// Generate docs/bytecode.js (used by docs/admin.html to deploy the
// contract from the owner's browser wallet) from the compiled artifact.
// Run from tools/:  node gen-bytecode-js.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const artifact = JSON.parse(
  readFileSync(join(here, "..", "contracts", "build", "FishAutoSwap.json"), "utf8")
);
const out =
  "// Generated by tools/gen-bytecode-js.mjs from contracts/build/FishAutoSwap.json — do not edit by hand.\n" +
  "// Compiler: " + artifact.compiler + "\n" +
  "var FISH_AUTOSWAP_BYTECODE = \"" + artifact.bytecode + "\";\n" +
  "var FISH_AUTOSWAP_ABI = " + JSON.stringify(artifact.abi) + ";\n";
writeFileSync(join(here, "..", "docs", "bytecode.js"), out);
console.log("docs/bytecode.js written, bytecode bytes:", (artifact.bytecode.length - 2) / 2);
